/* Hand-authored config_simd.h for the vendored OpenAL Soft build (normally
   generated by meson/CMake from config_simd.h.in based on detected compiler
   intrinsics). See //third_party/openal_soft:BUILD.openal.bazel, which
   selects the matching core/mixer/mixer_*.cpp file per @platforms//cpu. */
#if defined(__x86_64__) || defined(_M_X64) || defined(__i386__) || defined(_M_IX86)
#define HAVE_SSE 1
#define HAVE_SSE2 1
#define HAVE_SSE3 1
#define HAVE_SSE4_1 1
#define HAVE_SSE_INTRINSICS 1
#define HAVE_NEON 0
#else
#define HAVE_SSE 0
#define HAVE_SSE2 0
#define HAVE_SSE3 0
#define HAVE_SSE4_1 0
#define HAVE_SSE_INTRINSICS 0
#define HAVE_NEON 1
#endif
